const SWITCH_LABEL={"permanentBuffActive":"开局BUFF","lowHp": "濒死", "mpFull": "MP满", "mpLow": "MP≤20", "openingBuffActive": "开局BUFF", "allyDownBuffActive": "条件BUFF", "selfStateActive": "自身状态", "partyConditionActive": "队伍"};
const cond=field=>({field,op:'eq',value:true});
// Correct only the rules whose on/off switch disagreed with the game's own trigger data.
export function applyGameTiming(catalogId,rules){
 rules=applyTimingFixes(catalogId,rules);
 const plan=GAME_SWITCH_PLAN[catalogId];
 if(!plan||!Array.isArray(rules))return rules;
 return rules.map(rule=>{
  if(!(rule.effects||[]).some(e=>!['utility','recovery'].includes(e.type)))return rule;
  let conditions=(rule.conditions||[]).filter(c=>!(plan.drop||[]).includes(c.field));
  if(plan.add&&!conditions.some(c=>c.field===plan.add))conditions=[cond(plan.add),...conditions];
  const next={...rule,conditions};
  if(plan.ready&&rule.review==='pending'){
   next.review='ready';
   next.note=`游戏数据确认触发条件，按「${SWITCH_LABEL[plan.add]||'局内条件'}」开关计入。`;
   next.effects=(rule.effects||[]).map(e=>e.type==='statBuff'&&!e.runtime?{...e,runtime:{layer:'runtime-stat',stackGroup:`conditional:${catalogId}:${e.target}`,stackPolicy:'add',kind:'buff',lifetime:'condition',evidence:'game ProcessCondMst trigger'}}:e);
  }
  return next;
 });
}
function applyTimingFixes(catalogId,rules){
 const event=GAME_CONDITION_EVENTS[catalogId];
 if(event&&Array.isArray(rules))rules=rules.map(rule=>(rule.conditions||[]).some(c=>c.field==='conditionBuffActive')?{...rule,conditions:rule.conditions.map(c=>c.field==='conditionBuffActive'?{...c,field:event}:c)}:rule);
 const fix=GAME_TIMING_FIXES[catalogId];
 if(!fix||!Array.isArray(rules))return rules;
 return rules.map(rule=>{
  const part=String(rule.part);
  if(!fix.parts.some(p=>String(p)===part))return rule;
  let conditions=(rule.conditions||[]).filter(c=>!(fix.remove||[]).includes(c.field));
  for(const field of fix.add||[])if(!conditions.some(c=>c.field===field))conditions=[cond(field),...conditions];
  const next={...rule,conditions};
  if(fix.ready&&rule.review==='pending'){
   next.review='ready';
   next.note='游戏数据确认：开局 40 秒 BUFF，按开局BUFF开关计入。';
   next.effects=(rule.effects||[]).map(e=>e.type==='statBuff'&&!e.runtime?{...e,runtime:{layer:'runtime-stat',stackGroup:`${fix.ready}:${e.target}`,stackPolicy:'add',kind:'buff',lifetime:'opening-40s',evidence:'game ProcessMst trigger 10, 継続時間 2400'}}:e);
  }
  return next;
 });
}
// Display only: the calculator shows the game timing next to a skill whose name is unique in the catalog.
export function gameTimingLabelByName(name){
 const id=GAME_TIMING_NAMES_INDEX[String(name||'').trim()];
 return id?gameTimingLabel(id):'';
}
